(function(root){
'use strict';
function progress(sim){
 const rows=[],cfg=sim.cfg,homes=sim.buildings.filter(b=>b.hp>0&&!b.dead);
 if(sim.freeBuildingSlot()!==undefined&&cfg.buildingPopInterval>0)rows.push({id:'construction',label:'Prochaine maison',value:sim.buildingPopElapsed/cfg.buildingPopInterval,detail:Math.ceil(Math.max(0,cfg.buildingPopInterval-sim.buildingPopElapsed))+' s'});
 for(const b of homes){const job=b.training;if(job)rows.push({id:b.id,label:b.name+' · '+job.profile.name,value:job.elapsed/job.profile.duration,detail:job.elapsed>=job.profile.duration?'Prêt · limite de soldats atteinte':Math.ceil((job.profile.duration-job.elapsed)/sim.multiplier('production'))+' s'});else if(cfg.manualProduction)rows.push({id:b.id,label:b.name,value:b.readyNotice?1:0,detail:b.readyNotice||'Disponible · recruter',ready:!!b.readyNotice});}
 if(!cfg.manualProduction&&cfg.production){const next=homes.filter(b=>b.spawnRate>0).sort((a,b)=>(1-a.spawnProgress)/a.spawnRate-(1-b.spawnProgress)/b.spawnRate)[0];if(next){const p=sim.population(),wagon=sim.train.hp>0&&cfg.capacity>0&&p.aboard>=p.seats&&sim.wagons.length<16;rows.push({id:'legacy',label:wagon?'Production : nouveau wagon':'Production : prochain soldat',value:next.spawnProgress,detail:!wagon&&p.total>=p.limit?'Limite de soldats atteinte':Math.ceil((1-next.spawnProgress)*60/(next.spawnRate*sim.multiplier('production')))+' s · '+next.name});}}
 for(const b of homes)if(b.hp<b.maxHp&&b.regen>0)rows.push({id:'repair-'+b.id,label:'R\u00e9paration \u00b7 '+b.name,value:b.hp/b.maxHp,detail:Math.ceil((b.maxHp-b.hp)/(b.regen*sim.multiplier('regen')))+' s'});
 return rows;
}
function install(){
 const {sim}=root.roundCircleLab,stage=document.querySelector('#stage'),panel=document.createElement('div');panel.id='productionPanel';panel.innerHTML='<button id="productionHandle" type="button" aria-label="Déplacer la fenêtre de production">⠿ RECRUTEMENT</button><div id="productionRows"></div><button id="productionResize" type="button" aria-label="Redimensionner la fenêtre de production">◢</button>';stage.append(panel);root.installDrivingPanel(panel,stage,{key:'round-circle-production-layout-v1',handle:'#productionHandle',resize:'#productionResize'});
 const notification=document.createElement('div');notification.className='recruit-notification';notification.setAttribute('role','status');notification.setAttribute('aria-live','polite');stage.append(notification);
 let selected=null,selectionKey='',noticeUntil=0,resetId=sim.resetId;const rowNodes=new Map();
 const recruit=document.createElement('section');recruit.id='recruitment';recruit.hidden=true;document.querySelector('#inspect').prepend(recruit);
 function select(id){selected=id;selectionKey='';document.querySelector('button[data-tab="inspect"]').click();document.querySelector('#inspector').textContent='';document.querySelector('#entityFields').replaceChildren();updateSelection();}
 function updateSelection(){const home=sim.buildings.find(b=>b.id===selected);if(!home){recruit.hidden=true;return;}recruit.hidden=false;const key=home.id+':'+!!home.training+':'+(home.hp<=0)+':'+sim.ended+':'+sim.resetId;if(key!==selectionKey){selectionKey=key;recruit.replaceChildren();const title=document.createElement('h2');title.textContent=home.name;recruit.append(title);const summary=document.createElement('p');summary.className='recruit-status';recruit.append(summary);if(home.hp<=0){summary.textContent='Maison détruite';return;}const grid=document.createElement('div');grid.className='recruit-profiles';for(const profile of sim.soldierProfiles){const b=document.createElement('button');b.type='button';b.style.setProperty('--profile-color',profile.color);b.dataset.profile=profile.id;const name=document.createElement('strong');name.textContent=profile.name+' · '+profile.duration+' s';const role=document.createElement('span');role.textContent=profile.role;const stats=document.createElement('small'),s=profile.stats;stats.textContent=s.maxHp+' HP · '+s.damage+' dégâts · portée '+s.range+' · '+(1/s.cooldown).toFixed(1)+' tirs/s · mobilité '+s.speed;b.append(name,role,stats);b.onclick=()=>{if(sim.queueTraining(home.id,profile.id)){selectionKey='';update();}else notification.textContent='Recrutement indisponible : maison occupée ou limite atteinte.';};grid.append(b);}recruit.append(grid);}
 const summary=recruit.querySelector('.recruit-status');if(home.hp>0){summary.textContent=home.training?home.training.profile.name+' en préparation · '+Math.ceil(Math.max(0,home.training.profile.duration-home.training.elapsed)/sim.multiplier('production'))+' s':home.readyNotice||'Choisis un profil. Une commande à la fois par maison.';const full=sim.population().total+sim.buildings.filter(b=>b.hp>0&&b.training).length>=sim.cfg.actorLimit;recruit.querySelectorAll('button').forEach(b=>b.disabled=sim.ended||!!home.training||full||!sim.cfg.production);}}
 function update(){if(resetId!==sim.resetId){resetId=sim.resetId;selected=null;selectionKey='';notification.textContent='';}const host=panel.querySelector('#productionRows'),rows=progress(sim),ids=new Set(rows.map(r=>r.id));for(const [id,node] of rowNodes)if(!ids.has(id)){node.remove();rowNodes.delete(id);}for(const row of rows){let node=rowNodes.get(row.id);if(!node){node=document.createElement('div');const label=document.createElement(typeof row.id==='number'?'button':'strong'),bar=document.createElement('progress'),detail=document.createElement('small');if(typeof row.id==='number'){label.type='button';label.onclick=()=>select(row.id);}bar.max=1;node.append(label,bar,detail);host.append(node);rowNodes.set(row.id,node);}const [label,bar,detail]=node.children;label.textContent=row.label;bar.value=Math.round(Math.max(0,Math.min(1,row.value))*100)/100;bar.setAttribute('aria-label',row.label);bar.hidden=row.value===0;detail.textContent=row.detail;node.classList.toggle('ready',!!row.ready);}if(performance.now()>noticeUntil)notification.textContent='';updateSelection();}
 root.roundCircleProduction={update,select,clearSelection(){selected=null;recruit.hidden=true;},event(e){if(e.type==='training-complete'){notification.textContent=e.name+' prêt · '+(sim.get(e.homeId)?.name||'Maison')+' disponible';noticeUntil=performance.now()+8000;notification.onclick=()=>select(e.homeId);}update();}};update();
}
root.RoundCircleProduction={progress};if(typeof module!=='undefined')module.exports=root.RoundCircleProduction;if(typeof window!=='undefined')window.addEventListener('round-circle-ready',install,{once:true});
})(typeof window!=='undefined'?window:globalThis);
